// func compressNodeARM64(out *[16]uint32, cv *[8]uint32, block *[16]uint32, counter uint64, blockLen uint32, flags uint32)
TEXT ·compressNodeARM64(SB), 0, $16-40
	MOVD out+0(FP), R21
	MOVD cv+8(FP), R20
	MOVD block+16(FP), R19
	MOVD counter+24(FP), R16
	MOVWU blockLen+32(FP), R22
	MOVWU flags+36(FP), R23
	MOVWU 0(R20), R0
	MOVWU 4(R20), R1
	MOVWU 8(R20), R2
	MOVWU 12(R20), R3
	MOVWU 16(R20), R4
	MOVWU 20(R20), R5
	MOVWU 24(R20), R6
	MOVWU 28(R20), R7
	MOVD $0x6A09E667, R8
	MOVD $0xBB67AE85, R9
	MOVD $0x3C6EF372, R10
	MOVD $0xA54FF53A, R11
	MOVWU R16, R12
	LSR $32, R16, R13
	MOVWU R22, R14
	MOVWU R23, R15
	CALL scalarRounds<>(SB)

	// finalize
	EORW R8, R0
	MOVWU 0(R20), R24
	EORW R24, R8
	EORW R9, R1
	MOVWU 4(R20), R24
	EORW R24, R9
	EORW R10, R2
	MOVWU 8(R20), R24
	EORW R24, R10
	EORW R11, R3
	MOVWU 12(R20), R24
	EORW R24, R11
	EORW R12, R4
	MOVWU 16(R20), R24
	EORW R24, R12
	EORW R13, R5
	MOVWU 20(R20), R24
	EORW R24, R13
	EORW R14, R6
	MOVWU 24(R20), R24
	EORW R24, R14
	EORW R15, R7
	MOVWU 28(R20), R24
	EORW R24, R15
	MOVW R0, 0(R21)
	MOVW R1, 4(R21)
	MOVW R2, 8(R21)
	MOVW R3, 12(R21)
	MOVW R4, 16(R21)
	MOVW R5, 20(R21)
	MOVW R6, 24(R21)
	MOVW R7, 28(R21)
	MOVW R8, 32(R21)
	MOVW R9, 36(R21)
