// func compressChunkBlocksARM64(cv *[8]uint32, blocks *byte, n uint64, counter uint64, flags uint32)
TEXT ·compressChunkBlocksARM64(SB), 0, $16-36
	MOVD cv+0(FP), R20
	MOVD blocks+8(FP), R19
	MOVD n+16(FP), R21
	MOVD counter+24(FP), R16
	MOVWU flags+32(FP), R23
